def kosaraju(adj):
    n = len(adj)
    seen = [False] * n
    order = []
    for start in range(n):
        if seen[start]:
            continue
        seen[start] = True
        stack = [(start, iter(adj[start]))]
        while stack:
            node, neighbours = stack[-1]
            for nxt in neighbours:
                if not seen[nxt]:
                    seen[nxt] = True
                    stack.append((nxt, iter(adj[nxt])))
                    break
            else:
                stack.pop()
                order.append(node)
    reverse = [[] for _ in range(n)]
    for node in range(n):
        for nxt in adj[node]:
            reverse[nxt].append(node)
    assigned = [False] * n
    components = 0
    for start in reversed(order):
        if assigned[start]:
            continue
        components += 1
        assigned[start] = True
        stack = [start]
        while stack:
            node = stack.pop()
            for nxt in reverse[node]:
                if not assigned[nxt]:
                    assigned[nxt] = True
                    stack.append(nxt)
    return components

